 703: 	/* The SOME/IP-SD protocol supports two option runs. Runs meaning that two different starting indices with differing
 704: 	length can be provided. Of course, this only works if the indices in both runs are consecutive.
 705: 
 706: 		So, indices like this would work:
 707: 			1 2 3 ; 7 8
 708: 
 709: 		What wouldn't work is this:
 710: 			1 2 3 ; 7 9
 711: 			1 3 ; 7 8
 712: 	*/
 713: 
 714: 	size_t offsetToAddAt = sizeof(someipsdhdr) + sizeof(uint32_t) + indexEntry*sizeof(SomeIpSdEntry::someipsdhdrentry);
 715: 	auto hdrEntry = (SomeIpSdEntry::someipsdhdrentry *)(m_Data + offsetToAddAt);
 716: 
