 718: 	uint8_t lenFirstOption = hdrEntry->nrOpt1;
 719: 
 720: 	if (lenFirstOption == 0)
 721: 	{
 722: 		hdrEntry->indexFirstOption = indexOffset;
 723: 		++hdrEntry->nrOpt1;
 724: 		return true;
 725: 	}
 726: 
